#### Example 1: Extension Service Registration

```csharp
public class TexasClaimsExtension : IExtensionServiceRegistration
{
    public void ConfigureServices(IExtensionServiceCollection services)
    {
        // Register extension-specific services
        services.AddScoped<ITexasClaimValidator, TexasClaimValidator>();
        services.AddSingleton<ITexasReferenceDataCache, TexasReferenceDataCache>();
        services.AddTransient<ITexasClaimTransformer, TexasClaimTransformer>();

        // Register with options pattern
        services.Configure<TexasClaimsOptions>(options =>
        {
            options.EnableFastTracking = true;
            options.ValidationLevel = ValidationLevel.Strict;
        });

        // Register HttpClient with factory
        services.AddHttpClient<ITexasExternalService, TexasExternalService>(client =>
        {
            client.BaseAddress = new Uri("https://texas-api.example.com");
            client.Timeout = TimeSpan.FromSeconds(30);
        });
    }
}
```

