#### Example 2: Extension with Dependencies

```csharp
public class CaliforniaProviderExtension : ProviderExtensionBase
{
    private readonly ILogger<CaliforniaProviderExtension> _logger;
    private readonly IProviderRepository _repository; // Product service
    private readonly ICaliforniaLicenseValidator _validator; // Extension service
    private readonly IOptionsMonitor<CaliforniaOptions> _options;

    public CaliforniaProviderExtension(
        ILogger<CaliforniaProviderExtension> logger,
        IProviderRepository repository,
        ICaliforniaLicenseValidator validator,
        IOptionsMonitor<CaliforniaOptions> options)
    {
        _logger = logger;
        _repository = repository;
        _validator = validator;
        _options = options;
    }

    public override async Task<ProviderResult> ProcessAsync(
        ProviderContext context)
    {
        _logger.LogInformation(
            "Processing provider {ProviderId} for California",
            context.Provider.Id);

        var isValid = await _validator.ValidateAsync(
            context.Provider.LicenseNumber);

        if (!isValid)
            return ProviderResult.Rejected("Invalid California license");

        return ProviderResult.Approved();
    }
}
```

