#### Example 4: Factory Pattern for Complex Dependencies

```csharp
public interface ITexasReportGenerator { }

public class TexasReportFactory
{
    private readonly IServiceProvider _serviceProvider;

    public TexasReportFactory(IServiceProvider serviceProvider)
    {
        _serviceProvider = serviceProvider;
    }

    public ITexasReportGenerator Create(ReportType reportType)
    {
        return reportType switch
        {
            ReportType.Claims => _serviceProvider
                .GetRequiredService<TexasClaimsReportGenerator>(),
            ReportType.Provider => _serviceProvider
                .GetRequiredService<TexasProviderReportGenerator>(),
            _ => throw new ArgumentException($"Unknown report: {reportType}")
        };
    }
}

// Registration
services.AddSingleton<TexasReportFactory>();
services.AddTransient<TexasClaimsReportGenerator>();
services.AddTransient<TexasProviderReportGenerator>();
```

