### Real-World Example 1: Michigan Claims Extension with Complex Dependencies

**Context**: Michigan requires integration with external eligibility verification service during claims processing.

**Extension Implementation**:

```csharp
public class MichiganClaimsExtension : IExtensionServiceRegistration
{
    public void ConfigureServices(IExtensionServiceCollection services)
    {
        // Primary extension service
        services.AddScoped<IMichiganClaimProcessor, MichiganClaimProcessor>();

        // HttpClient for external service
        services.AddHttpClient<IMichiganEligibilityService, MichiganEligibilityService>()
            .AddPolicyHandler(GetRetryPolicy())
            .AddPolicyHandler(GetCircuitBreakerPolicy());

        // Caching
        services.AddSingleton<IMichiganEligibilityCache, MichiganEligibilityCache>();

        // Configuration
        services.AddOptions<MichiganEligibilityOptions>()
            .ValidateDataAnnotations()
            .ValidateOnStart();
    }
}

public class MichiganClaimProcessor : IMichiganClaimProcessor
{
    private readonly ILogger<MichiganClaimProcessor> _logger;
    private readonly IClaimRepository _claimRepo; // Product service
    private readonly IMichiganEligibilityService _eligibility; // Extension service
    private readonly IMichiganEligibilityCache _cache; // Extension service

    public MichiganClaimProcessor(
        ILogger<MichiganClaimProcessor> logger,
        IClaimRepository claimRepo,
        IMichiganEligibilityService eligibility,
        IMichiganEligibilityCache cache)
    {
        _logger = logger;
        _claimRepo = claimRepo;
        _eligibility = eligibility;
        _cache = cache;
    }

    public async Task<ClaimResult> ProcessAsync(ClaimContext context)
    {
        // Check cache first
        if (_cache.TryGet(context.MemberId, out var cachedResult))
        {
            _logger.LogDebug("Eligibility found in cache");
            return cachedResult;
        }

        // Call external service
        var eligible = await _eligibility.CheckEligibilityAsync(context.MemberId);

        // Cache result
        _cache.Set(context.MemberId, eligible);

        return eligible ? ClaimResult.Approved() : ClaimResult.Denied("Not eligible");
    }
}
```

**Testing with Mocks**:

```csharp
public class MichiganClaimProcessorTests
{
    [Fact]
    public async Task ProcessClaim_WhenEligible_ApprovesClaim()
    {
        // Arrange
        var mockEligibility = new Mock<IMichiganEligibilityService>();
        mockEligibility
            .Setup(x => x.CheckEligibilityAsync(It.IsAny<string>()))
            .ReturnsAsync(true);

        var services = new ServiceCollection();
        services.AddLogging();
        services.AddTransient(_ => mockEligibility.Object);
        services.AddSingleton<IMichiganEligibilityCache, InMemoryCache>();
        services.AddScoped<IMichiganClaimProcessor, MichiganClaimProcessor>();
        services.AddScoped<IClaimRepository, MockClaimRepository>();

        var provider = services.BuildServiceProvider();
        var processor = provider.GetRequiredService<IMichiganClaimProcessor>();

        // Act
        var result = await processor.ProcessAsync(CreateTestContext("M12345"));

        // Assert
        Assert.True(result.IsApproved);
        mockEligibility.Verify(x => x.CheckEligibilityAsync("M12345"), Times.Once);
    }
}
```

