### Real-World Example 2: Multi-Tenant Scope Management

**Context**: California extension needs scoped DbContext per request in multi-tenant environment.

**Implementation**:

```csharp
public class CaliforniaDataExtension : IExtensionServiceRegistration
{
    public void ConfigureServices(IExtensionServiceCollection services)
    {
        // Register scoped DbContext (NOT singleton!)
        services.AddScoped<CaliforniaExtensionDbContext>(provider =>
        {
            var tenantContext = provider.GetRequiredService<ITenantContext>();
            var options = new DbContextOptionsBuilder<CaliforniaExtensionDbContext>()
                .UseSqlServer(GetConnectionString(tenantContext.TenantId))
                .Options;
            return new CaliforniaExtensionDbContext(options);
        });

        services.AddScoped<ICaliforniaDataService, CaliforniaDataService>();
    }
}

public class CaliforniaDataService : ICaliforniaDataService
{
    private readonly CaliforniaExtensionDbContext _context;
    private readonly ITenantContext _tenantContext;

    public CaliforniaDataService(
        CaliforniaExtensionDbContext context,
        ITenantContext tenantContext)
    {
        _context = context;
        _tenantContext = tenantContext;
    }

    public async Task<CaliforniaData> GetDataAsync(string id)
    {
        // DbContext automatically scoped to current tenant's connection
        return await _context.CaliforniaData
            .FirstOrDefaultAsync(d => d.Id == id);
    }
}
```

**Multi-Tenant Invocation**:

```csharp
public class ExtensionInvoker
{
    private readonly IServiceScopeFactory _scopeFactory;

    public async Task<TResult> InvokeExtensionAsync<TResult>(
        string tenantId, Func<IServiceProvider, Task<TResult>> action)
    {
        using var scope = _scopeFactory.CreateScope();
        var services = scope.ServiceProvider;

        // Set tenant context for this scope
        var tenantContext = services.GetRequiredService<ITenantContext>();
        tenantContext.SetTenant(tenantId);

        // Execute with scoped services
        return await action(services);
    }
}
```

