### Use Case Scenario: Preventing Service Override Conflict

**Scenario**: Developer attempts to register core interface that should not be overridden.

**Incorrect Approach** (Will Fail):

```csharp
public class BadExtension : IExtensionServiceRegistration
{
    public void ConfigureServices(IExtensionServiceCollection services)
    {
        // WRONG! IClaimValidator is reserved by product
        services.AddScoped<IClaimValidator, CustomValidator>();
        // Throws: ExtensionServiceException - Cannot register reserved interface
    }
}
```

**Correct Approach**:

```csharp
public class GoodExtension : IExtensionServiceRegistration
{
    public void ConfigureServices(IExtensionServiceCollection services)
    {
        // Create extension-specific interface
        services.AddScoped<ITexasClaimValidator, TexasClaimValidator>();
    }
}

public class TexasClaimProcessor : IClaimProcessor
{
    private readonly IClaimValidator _standardValidator; // Product service
    private readonly ITexasClaimValidator _texasValidator; // Extension service

    public TexasClaimProcessor(
        IClaimValidator standardValidator,
        ITexasClaimValidator texasValidator)
    {
        _standardValidator = standardValidator;
        _texasValidator = texasValidator;
    }

    public async Task<ValidationResult> ValidateAsync(Claim claim)
    {
        // Run both standard and Texas-specific validation
        var standardResult = await _standardValidator.ValidateAsync(claim);
        if (!standardResult.IsValid) return standardResult;

        return await _texasValidator.ValidateAsync(claim);
    }
}
```
